package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
class ReceivableTreasuryTest extends ApiTestSupport {
 String auth,account;UUID branch;
 @BeforeEach void fixture()throws Exception{auth=token(company);branch=db.queryForObject("SELECT id FROM branch WHERE tenant_id=?",UUID.class,tenant);account=createAccount(branch,"BANK");}
 String createAccount(UUID branch,String code)throws Exception{return postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"code",code,"name","Conta "+code,"kind","BANK"),201).get("id").asText();}
 JsonNode title(String ref)throws Exception{var c=postApi("/api/v1/customers",auth,Map.of("code",ref,"name","Cliente","taxIdentifier","","contactName","","email","","phone","","address","","notes",""),201);return postApi("/api/v1/receivables",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"customerId",c.get("id").asText(),"reference",ref,"document","","description","Título de teste","issuedOn","2020-01-01","dueOn","2020-02-01","amount","100"),201);}
 String path(JsonNode t){return "/api/v1/receivables/"+t.get("id").asText();}
 Map<String,Object> receipt(UUID key,String amount,String bank){var m=new HashMap<String,Object>();m.put("receiptId",key);m.put("amount",amount);m.put("receivedOn","2020-02-01");m.put("method","PIX");m.put("reference","");m.put("note","Recebimento de teste");m.put("treasuryAccountId",bank);return m;}
 Map<String,Object> reversal(UUID key){return Map.of("requestId",key,"note","Correção de teste");}
 void balance(String amount){assertEquals(0,new BigDecimal(amount).compareTo(db.queryForObject("SELECT balance FROM treasury_account WHERE tenant_id=? AND id=?",BigDecimal.class,tenant,UUID.fromString(account))));}
 long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE tenant_id=?",Long.class,tenant);}
 @Test void linkedReceiptCreditsAndReversalDebitsExactlyOnce()throws Exception{var t=title("ONE");UUID key=UUID.randomUUID(),r=UUID.randomUUID();var input=receipt(key,"40",account);var posted=postApi(path(t)+"/receipts",auth,input,200);balance("40");assertEquals(account,posted.get("treasuryAccountId").asText());assertEquals(posted,postApi(path(t)+"/receipts",auth,receipt(key,"40.00",account),200));String endpoint=path(t)+"/receipts/"+key+"/reverse";var reversed=postApi(endpoint,auth,reversal(r),200);balance("0");assertEquals(reversed,postApi(endpoint,auth,reversal(r),200));assertEquals(reversed,postApi(path(t)+"/receipts",auth,input,200));assertEquals(2,count("treasury_operation"));var entries=getApi("/api/v1/treasury/accounts/"+account+"/entries",auth,200).get("items");assertEquals("RECEIVABLE_REVERSAL",entries.get(0).get("origin").asText());assertEquals("RECEIVABLE_RECEIPT",entries.get(1).get("origin").asText());}
 @Test void spentFundsPreventReversalAndPreserveReceipt()throws Exception{var t=title("ONE");UUID key=UUID.randomUUID();postApi(path(t)+"/receipts",auth,receipt(key,"100",account),200);postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"sourceId",account,"amount","100","note","Retirada após recebimento"),200);postApi(path(t)+"/receipts/"+key+"/reverse",auth,reversal(UUID.randomUUID()),409);balance("0");assertEquals("RECEIVED",getApi(path(t),auth,200).get("status").asText());assertEquals(2,count("treasury_operation"));}
 @Test void creditOverflowRollsBackEntireReceipt()throws Exception{var t=title("ONE");postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"destinationId",account,"amount","99999999999999999.99","note","Crédito limite de teste"),200);postApi(path(t)+"/receipts",auth,receipt(UUID.randomUUID(),"1",account),409);assertEquals(0,count("receivable_receipt"));assertEquals("OPEN",getApi(path(t),auth,200).get("status").asText());balance("99999999999999999.99");}
 @Test void legacyExternalReceiptsDoNotRequireTreasuryPermissions()throws Exception{var t=title("ONE");db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission LIKE 'treasury:%'",tenant);UUID key=UUID.randomUUID();postApi(path(t)+"/receipts",auth,receipt(key,"10",account),403);var external=postApi(path(t)+"/receipts",auth,receipt(key,"10",null),200);assertTrue(external.get("treasuryOperationId").isNull());postApi(path(t)+"/receipts/"+key+"/reverse",auth,reversal(UUID.randomUUID()),200);balance("0");assertEquals(0,count("treasury_operation"));}
 @Test void accountScopeAndReplayCannotBeBypassed()throws Exception{var t=title("ONE");UUID key=UUID.randomUUID();postApi(path(t)+"/receipts",auth,receipt(key,"20",account),200);postApi(path(t)+"/receipts",auth,receipt(key,"20",null),409);UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","OTHER","name","Outra"),201).get("id").asText());String bank=createAccount(other,"OTHER");UUID user=db.queryForObject("SELECT id FROM app_user WHERE tenant_id=?",UUID.class,tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE id=?",user);db.update("INSERT INTO user_branch_access(tenant_id,user_id,branch_id) VALUES(?,?,?)",tenant,user,branch);postApi(path(t)+"/receipts",auth,receipt(UUID.randomUUID(),"10",bank),404);balance("20");}
 @Test void duplicateReversalKeyRollsBackTreasuryDebit()throws Exception{var t=title("ONE");UUID a=UUID.randomUUID(),b=UUID.randomUUID(),r=UUID.randomUUID();postApi(path(t)+"/receipts",auth,receipt(a,"40",account),200);postApi(path(t)+"/receipts",auth,receipt(b,"60",account),200);postApi(path(t)+"/receipts/"+a+"/reverse",auth,reversal(r),200);postApi(path(t)+"/receipts/"+b+"/reverse",auth,reversal(r),409);balance("60");assertEquals(3,count("treasury_operation"));assertEquals("60.00",getApi(path(t),auth,200).get("receivedAmount").asText());}
 @Test void concurrentReceiptAndReversalRetriesProduceSingleEntries()throws Exception{var t=title("ONE");UUID key=UUID.randomUUID();var input=receipt(key,"100",account);assertEquals(List.of(200,200),concurrent(path(t)+"/receipts",input,path(t)+"/receipts",input));balance("100");String endpoint=path(t)+"/receipts/"+key+"/reverse";var r=reversal(UUID.randomUUID());assertEquals(List.of(200,200),concurrent(endpoint,r,endpoint,r));balance("0");assertEquals(2,count("treasury_operation"));}
 @Test void concurrentReversalAndWithdrawalCannotOverdraw()throws Exception{var t=title("ONE");UUID key=UUID.randomUUID();postApi(path(t)+"/receipts",auth,receipt(key,"100",account),200);var withdrawal=Map.of("requestId",UUID.randomUUID(),"sourceId",account,"amount","100","note","Retirada concorrente");assertEquals(List.of(200,409),concurrent(path(t)+"/receipts/"+key+"/reverse",reversal(UUID.randomUUID()),"/api/v1/treasury/movements",withdrawal));balance("0");assertEquals(2,count("treasury_operation"));}
 @Test void profilesAndUserCreationAcceptAllCurrentPermissions()throws Exception{var permissions=br.com.erp.user.UserService.PERMISSIONS.stream().sorted().toList();assertTrue(permissions.size()>30);var profile=postApi("/api/v1/access-profiles",auth,Map.of("name","Todos os acessos","permissions",permissions),201);assertEquals(permissions.size(),profile.get("permissions").size());postApi("/api/v1/users",auth,Map.of("name","Gestor de teste","email","manager@example.com","password",password,"permissions",permissions),201);}
 List<Integer> concurrent(String p1,Object b1,String p2,Object b2)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();return status(p1,b1);});var b=pool.submit(()->{gate.await();return status(p2,b2);});gate.countDown();var result=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(result);return result;}}
 int status(String path,Object body)throws Exception{return http.perform(post(path).header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(body))).andReturn().getResponse().getStatus();}
}
